Read `src/auth/session.ts`, `src/api/routes.ts:8-13`, `test/session.test.ts`, plus `tsconfig.json` (both `src/auth/**` and `test/**` are in `include`). Plan: two new files, nothing touched.

`login` starts the new session with `createSession(user.id)` — one argument, the user id, returning the `Session` (only `.token` is read). So refresh mirrors that with the existing session's `userId`.

**File 1 — `src/auth/refresh.ts`**

```ts
import { createSession, getSession, revokeSession, type Session } from "./session.ts";

/** Swap a live token for a fresh session for the same user; undefined if the token is not live. */
export function refreshSession(token: string): Session | undefined {
  const current = getSession(token);
  if (!current) return undefined;
  revokeSession(token);
  return createSession(current.userId);
}
```

**File 2 — `test/refresh.test.ts`**

```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { createSession, getSession, resetSessions } from "../src/auth/session.ts";
import { refreshSession } from "../src/auth/refresh.ts";

beforeEach(() => resetSessions());

test("refreshSession replaces a live token with a new session for the same user", () => {
  const original = createSession("u_1");
  const refreshed = refreshSession(original.token);
  assert.ok(refreshed);
  assert.notEqual(refreshed.token, original.token);
  assert.equal(refreshed.userId, "u_1");
  assert.equal(getSession(original.token), undefined);
  assert.equal(getSession(refreshed.token)?.userId, "u_1");
});

test("refreshSession returns undefined for an unknown token", () => {
  assert.equal(refreshSession("nope"), undefined);
});

test("refreshSession leaves other sessions alone", () => {
  const mine = createSession("u_1");
  const other = createSession("u_2");
  refreshSession(mine.token);
  assert.equal(getSession(other.token)?.userId, "u_2");
});
```

